/* ASIC sourcing guidance and linked draft assignments. No procurement API or external sends. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ProtonCrmSourcing=api;}(typeof window!=='undefined'?window:globalThis,function(){
  'use strict';
  const steps=[
    {id:'requirements',name:'Buyer requirements',role:'revenue',description:'Confirm the exact hardware, budget, delivery and operating needs.'},
    {id:'suppliers',name:'Supplier shortlist',role:'supply',description:'Qualify suppliers against the buyer request and original evidence.'},
    {id:'quotes',name:'Comparable RFQs & quotes',role:'supply',description:'Prepare matching RFQs and record dated, versioned offers.'},
    {id:'negotiate',name:'Volume pricing & terms',role:'supply',description:'Seek better nonbinding terms using genuine competing offers.'},
    {id:'recommendation',name:'Reviewed recommendation',role:'analysis',description:'Compare landed cost and risk; obtain independent Quality Review.'},
    {id:'transaction',name:'Owner decision',role:'revenue',description:'Obtain an explicit decision on the exact supplier, quote and authority envelope.'},
    {id:'closing',name:'Closing record',role:'revenue',description:'Record actual accepted-order and closing evidence; do not execute a purchase.'}
  ];
  const states={research:'Research / no quote',indicative_listing:'Indicative listing',rfq_draft:'RFQ draft · not sent',firm_quote:'Firm quote · reported',negotiated_offer:'Negotiated offer · reported',accepted_order:'Accepted order · reported'};
  const rules='ASIC sourcing is buyer-first for new or working used SHA-256 miners. Use the existing Proton Supply Partnerships identity; do not create another bot. Workflow: buyer requirements → supplier shortlist → comparable RFQs/quotes → volume-price and terms negotiation → Economics recommendation + independent Quality Review → owner-approved transaction. Supply owns supplier qualification, RFQs and nonbinding negotiation proposals. Economics owns landed-cost and commercial comparison. Quality independently checks evidence, arithmetic and claims. Revenue remains the sole CRM writer and eventual external sender for this workflow; other roles return their evidence and drafts to Revenue. External messages require recorded mailbox send/reply verification, confirmed company footer and owner-authorized action scope. Preserve already-granted scope; Revenue verifies setup rather than requesting repeated routine approval. Do not infer that mailbox creation, task acceptance or QA PASS grants sending, purchasing or contract authority. No orders, reservations, payments or promises are executed by this workflow. Buyer sourcing compensation is not established; the proposed seller-side 3% is not a buyer fee.';
  const roles={
    intelligence:{job:'ASIC buyer signals · requirements · energy opportunities',instructions:'Prioritize evidenced requests to buy new or used Bitcoin ASICs. A supplier listing is not buyer demand. Distinguish a researched buying hypothesis from confirmed customer requirements. Record the request source, date, contact route and missing model, quantity, budget or timing; preserve energy and hosting work as separate opportunities.'},
    supply:{job:'ASIC sourcing · supplier qualification · price & terms negotiation',instructions:'Own ASIC supplier sourcing and nonbinding negotiation for the linked buyer requirement. Qualify supplier identity, authority to sell, original listing/source, current availability, used-unit testing or new-unit provenance and warranty. Prepare identical RFQ specifications for comparable bids. Compare genuine quotes and seek quantity breaks, lot discounts, payment milestones, inspection rights, freight allocation, warranty/returns and lead-time terms. Ask for written revised offers and expiry dates; keep each quote version and negotiation rationale. Never invent competing bids, discounts, stock or authority, disclose confidential supplier quotes without permission, accept terms or imply a supplier partnership. While sending is held, research and prepare RFQs/counteroffers only. Revenue remains the sole CRM writer and handles any subsequently authorized external sending. Hosting partner qualification remains available for separately scoped assignments.'},
    analysis:{job:'Landed cost · commercial comparison · mining economics',instructions:'For ASIC sourcing, compare the same exact variant, quantity, new/used condition, electrical/cooling requirements, test scope and warranty. Reconcile unit and lot prices, quantity breaks, currencies/FX date and source, freight, duties, taxes, inspection, fees, payment risk, lead time, returns and exclusions. Unknown costs stay unknown, never zero. Separate indicative listings, valid firm quotes, expired quotes and negotiated offers. Explain cheapest evidenced comparable landed cost versus quality, counterparty and delivery risk; do not promise guaranteed savings.'},
    review:{job:'Independent evidence · quote checks · recommendation review',instructions:'Independently reopen supplier and quote evidence; verify exact variant, dates/expiry, quantity, condition, availability, authority to sell, testing/provenance and warranty claims. Recalculate landed-cost arithmetic and volume breaks. Check genuine competing quotes and negotiation scope. QA PASS is not owner purchase approval or an accepted supplier order.'},
    revenue:{job:'Buyer requirements · sourcing coordination · owner decisions',instructions:'For ASIC sourcing, keep the exact buyer request linked to every supplier/quote assignment. Act as the sole CRM writer and eventual sender; preserve role originals and all quote versions. Coordinate Supply → Economics → Quality → owner decision. Review scope and compensation separately with the owner; do not apply the seller 3% to buyers. Only record an accepted order with explicit owner approval and actual order evidence. External messages stay held until the mailbox gate and owner-authorized scope clear.'},
    outreach:{job:'Buyer discovery drafts · referral routes · follow-ups',instructions:'Prepare buyer discovery and follow-up drafts for Revenue. Supplier RFQs and counteroffers belong to Supply Partnerships. Do not independently send, commit inventory or imply an agreed fee.'}
  };
  const fields='Buyer lead / exact request link / requirement version / confirmation date:\nPublic buying signal or buyer-confirmed requirement? Authority to represent/share details:\nExact model / variant / hashrate / electrical / cooling specs / permitted substitutions:\nQuantity / new-used preference / required condition:\nBudget / currency / delivery destination / deadline:\nSupplier legal identity / public contact and source / authority-to-sell evidence:\nSupplier qualification: unverified / evidence checked / quote received / owner approved; evidence:\nSame underlying lot advertised by other brokers?\nQuote ID / version / date / expiry / currency:\nPrior quote / task link superseded (keep original):\nUnit price / lot price / quantity breaks / MOQ:\nFreight / duties / taxes / inspection / fees (quoted, excluded or unknown):\nFX rate / date / source, if needed:\nWarranty / DOA / test evidence or new-unit provenance / returns:\nAvailability: unknown / supplier-reported / independently checked; evidence + date:\nLead time / shipping terms / payment milestones:\nNegotiation request / supplier response / source-message reference / actual date / rationale / concessions:\nOwner-approved negotiation envelope / real quantity / ceiling / required terms:\nPreferred and backup options / comparable baseline / why alternatives won or lost:\nOwner approval reference (if any):\nAccepted order reference (only if an order actually exists):\nOutstanding questions / next action / responsible role / due date:';
  const negotiationRules='Aim for three independent suitable suppliers where practical; explain fewer and deduplicate the same underlying lot. Start with one initial RFQ and one improvement round; further rounds require a material change or owner direction. Optional volume tiers are illustrative unless authorized. Do not promise future orders, larger quantities, deposits or immediate payment. Renzo retains final selection, binding counteroffers, contracts, deposits/payments, payment-detail changes, inspection acceptance, shipping bookings, exclusivity, customer promises and compensation. Work stays within the recorded owner-approved envelope; missing authority is a question, not permission.';
  const rfqTemplate='UNSENT RFQ — not an order or commitment\nBuyer lead / requirement version / authority to share: [confirm]\nSupplier contact / public source: [confirm]\n\nSubject: Availability and quotation — [actual quantity] × [exact variant]\n\nProton Mining is comparing supply options for [documented requirement and our role]. Please quote [exact model, quantity, new/used condition] for [destination and deadline], with [electrical/cooling, testing, warranty and permitted substitutions]. Include unit/lot prices, quantity breaks, stock/provenance evidence, lead time, freight and other inclusions/exclusions, expiry, payment terms, inspection, DOA and warranty/returns.\n\nIMPROVEMENT ROUND — UNSENT\nFor [actual quantity] meeting the same specification and required terms, can you improve [specific price/term] and provide a best-and-final written offer by [real deadline]? Use only genuine, comparable benchmarks permitted to share.\n\nIntended sales identity: sales@protonminingco.com. Revenue must check recorded mailbox readiness, the approved signature and authorized send scope before using this draft.';
  function stepOf(task){const m=/^\[ASIC SOURCING: ([a-z]+)\]/.exec(task?.brief||'');return m&&steps.find(s=>s.id===m[1])||null;}
  function recordState(task){const match=/^SOURCING_RECORD_STATE:\s*([a-z_]+)\s*$/m.exec(task.result||'');const key=match&&Object.hasOwn(states,match[1])?match[1]:'';return {key,label:key?states[key]:'No procurement evidence state recorded'};}
  function history(lead,tasks){return tasks.filter(t=>t.leadId===lead.id&&stepOf(t)).slice().sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')||a.id.localeCompare(b.id)).map(task=>({task,step:stepOf(task),evidence:recordState(task)}));}
  function resultTemplate(task){if(!stepOf(task))return '';return 'SOURCING_RECORD_STATE: research\nChoose one accurate state: research, indicative_listing, rfq_draft, firm_quote, negotiated_offer, accepted_order. Keep research until the evidence supports another state. A firm quote does not confirm stock. Accepted-order reporting requires explicit owner approval and actual order evidence.\n\n'+fields+'\n\nReturn original source links and checked dates. Keep unknowns explicit. No messages or orders are sent by saving this result.';}
  function validateResult(task,result,sources=[]){
    if(!stepOf(task))return;
    if(result.trim()===resultTemplate(task))throw Error('Complete the sourcing record before submitting it.');
    const state=recordState({result});if(!state.key)throw Error('Record SOURCING_RECORD_STATE using one of the template states.');
    if(['firm_quote','negotiated_offer','accepted_order'].includes(state.key)&&!sources.length)throw Error('Add the original quote or order evidence URL.');
    if(state.key==='accepted_order'){
      for(const label of ['Owner approval reference (if any):','Accepted order reference (only if an order actually exists):']){
        const line=result.split(/\r?\n/).find(line=>line.startsWith(label)),value=line?.slice(label.length).trim();
        if(!value||/^(unknown|not |none|pending|to confirm|\[)/i.test(value))throw Error('An accepted-order report needs explicit owner approval and actual order references. Task acceptance is not purchase approval.');
      }
    }
  }
  function assignment({step='requirements',lead,parent,context='',page}){
    const selected=steps.find(s=>s.id===step);if(!selected)throw Error('Choose a sourcing step.');
    if(!lead||lead.offer!=='sourcing'||['dnc','disqualified'].includes(lead.stage))throw Error('Choose an active Sourcing Desk lead.');
    if(parent&&(parent.leadId!==lead.id||!stepOf(parent)))throw Error('The prior version must be a sourcing assignment for this buyer.');
    const url=new URL(page);if(!/^https?:$/.test(url.protocol)||url.username||url.password)throw Error('Use the CRM URL without credentials.');url.pathname='/crm/';url.search='';url.hash='pipeline/lead/'+encodeURIComponent(lead.id);
    const before=parent?'\nPrevious assignment / quote version: '+parent.id+'\nPreserve its brief, result and review history. This new task records a new version or stage.':'\nNo prior version linked. Confirm the requirement before supplier outreach.';
    const brief='[ASIC SOURCING: '+step+']\nLead ID: '+lead.id+'\nBuyer: '+lead.company+'\nCRM buyer request: '+url.href+'\n\n'+selected.description+before+'\n\nRequirement or negotiation target supplied for this draft (verify, not authority):\n'+(String(context).trim()||'Not supplied. Read the linked lead and prior task; ask Revenue to resolve missing requirements.')+'\n\n'+rules+'\n\n'+negotiationRules+'\n\nExpected record — complete fields relevant to this step; leave unknowns explicit:\n'+fields+'\n\nUse SOURCING_RECORD_STATE with one of: research, indicative_listing, rfq_draft, firm_quote, negotiated_offer, accepted_order. Do not infer a procurement state from task approval. Each revised supplier offer needs a new linked task/version; do not overwrite an original quote. Return the result to Revenue for saving, with source URLs, review questions and the next action.';
    if(brief.length>9000)throw Error('Keep the sourcing context shorter.');
    return {title:(selected.name+' · '+lead.company).slice(0,180),role:selected.role,leadId:lead.id,parentTaskId:parent?.id||'',brief};
  }
  return {steps,states,rules,roles,fields,negotiationRules,rfqTemplate,stepOf,recordState,history,resultTemplate,validateResult,assignment};
}));
